def analyze_land(pnu_or_address: str, input_type: str = "auto", zones_json: str = "[]") -> str:
    """AG-light Worker로 토지 규제를 분석합니다. pnu_or_address는 PNU(19자리) 또는 주소."""
    import urllib.request
    import json
    import os
    base_url = os.getenv("AG_LIGHT_URL", "http://localhost:8787")
    url = f"{base_url}/land/analyze"
    try:
        zones = json.loads(zones_json) if zones_json else []
    except json.JSONDecodeError:
        zones = []
    if input_type == "auto":
        input_type = "pnu" if len(pnu_or_address) == 19 and pnu_or_address.isdigit() else "address"
    payload = json.dumps({"input": pnu_or_address, "input_type": input_type, "zones": zones, "include_law": True}).encode("utf-8")
    req = urllib.request.Request(url, data=payload, headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            data = json.loads(resp.read().decode("utf-8"))
        parts = []
        if data.get("pnu"):
            parts.append(f"PNU: {data['pnu'].get('pnu', '')}")
        zi = data.get("zone_info", {})
        if zi.get("zones"):
            parts.append(f"용도지역: {', '.join(zi['zones'])}")
        if zi.get("bcr_limit") is not None:
            parts.append(f"건폐율 상한: {zi['bcr_limit']}%")
        if zi.get("far_limit") is not None:
            parts.append(f"용적률 상한: {zi['far_limit']}%")
        regs = data.get("regulations", {})
        if regs.get("height_limit_m"):
            parts.append(f"높이제한: {regs['height_limit_m']}m")
        if regs.get("sunlight_applies"):
            parts.append("정북일조 사선제한 적용")
        if regs.get("corner_cutoff_required"):
            parts.append("가각전제 적용")
        restrictions = data.get("restrictions", [])
        if restrictions:
            parts.append(f"규제 요약: {'; '.join(restrictions)}")
        laws = data.get("law_articles", {})
        if laws.get("total_count"):
            parts.append(f"관련 법조항 {laws['total_count']}건")
        return "\n".join(parts) if parts else json.dumps(data, ensure_ascii=False)[:3000]
    except Exception as e:
        return f"분석 실패: {e}"
